// جلب متزامن لملف الدورة في صفحات الدروس فقط: يضمن العرض مع أي نسخة app.js مخزنة
(function(){
  try{
    var q=new URLSearchParams(location.search);
    if(!q.get("lesson"))return;
    var secs=(window.SITE_DATA&&window.SITE_DATA.sections)||[];
    var sec=null;
    for(var i=0;i<secs.length;i++){if(secs[i].id===q.get("section")){sec=secs[i];break;}}
    if(!sec)return;
    var owner=sec;
    if(q.get("course")&&sec.courses){for(var k=0;k<sec.courses.length;k++){if(sec.courses[k].id===q.get("course")){owner=sec.courses[k];break;}}}
    if(!owner||(owner.__full&&owner.lessons&&owner.lessons.every(function(l){return l&&l.segments})))return;
    var key=owner.id;
    var xhr=new XMLHttpRequest();
    xhr.open("GET","assets/data/"+(window.DATA_FILES[key]||key+".js")+"?v="+window.DATA_V,false);
    xhr.send(null);
    if(xhr.status>=200&&xhr.status<300){
      (0,eval)(xhr.responseText);
      var full=window.SITE_COURSES[key];
      if(full&&full.lessons){owner.lessons=full.lessons;owner.__full=true;}
    }
  }catch(e){}
})();
